<script setup>
import {computed,onBeforeUnmount,onMounted,ref} from 'vue';
import {useAccess} from '../composables/access.js';
import {api} from '../services/accounting.js';
import {reconciliationProposalError} from '../services/reconciliation-proposals.js';
import {cents,decimal,displayMoney} from '../../../shared/money.js';
import {reconciliationSignedAmount} from '../../../shared/reconciliation-proposals.js';
import FormDialog from './FormDialog.vue';
import SubaccountInput from './SubaccountInput.vue';
const props=defineProps({report:{type:Object,required:true},movement:{type:Object,required:true},post:Boolean,initial:Object}),emit=defineEmits(['close','saved']);
const {can}=useAccess(),accounts=ref([]),loading=ref(true),busy=ref(false),error=ref('');let disposed=false,key=0;
const existing=props.report.snapshot.proposals.find(row=>String(row.movement_id)===String(props.movement.id)),bankAmount=reconciliationSignedAmount(props.movement.amount),absolute=decimal(bankAmount<0n?-bankAmount:bankAmount);
const sourceLines=props.initial?.counter_lines||existing?.lines.filter(line=>line.code!==props.report.account.code),requestId=props.initial?.request_id||crypto.randomUUID();
const form=ref({date:props.initial?.date||existing?.date||props.movement.date,concept:(props.initial?.concept||existing?.concept||props.movement.concept).slice(0,200),remember:props.initial?.remember??false,rule_concept:props.initial?.rule_concept||existing?.rule_concept||props.movement.concept.slice(0,200),counter_lines:sourceLines?sourceLines.map(line=>({key:key++,account_id:line.account_id?String(line.account_id):'',debit:line.debit,credit:line.credit})):[{key:key++,account_id:'',debit:bankAmount<0n?absolute:'0.00',credit:bankAmount>0n?absolute:'0.00'}]});
const totals=computed(()=>{try{let debit=bankAmount>0n?bankAmount:0n,credit=bankAmount<0n?-bankAmount:0n;for(const line of form.value.counter_lines){debit+=cents(line.debit.trim()||'0');credit+=cents(line.credit.trim()||'0');}return {valid:true,debit,credit,difference:debit-credit};}catch{return {valid:false};}});
const canSave=computed(()=>can('accounting_write')&&!busy.value&&!loading.value&&totals.value.valid&&totals.value.difference===0n&&form.value.counter_lines.every(line=>accounts.value.some(account=>String(account.id)===String(line.account_id)))&&(!form.value.remember||form.value.rule_concept.trim().length>=3));
onMounted(async()=>{try{const rows=await api('/accounts?kind=subaccount');if(!disposed)accounts.value=rows.filter(row=>row.id!==props.report.account_id);}catch(cause){error.value=reconciliationProposalError(cause);}finally{loading.value=false;}});
onBeforeUnmount(()=>disposed=true);
function addLine(){form.value.counter_lines.push({key:key++,account_id:'',debit:'0.00',credit:'0.00'});}
function name(accountId){return accounts.value.find(row=>String(row.id)===String(accountId))?.description||'';}
async function save(){if(!canSave.value)return;busy.value=true;error.value='';try{const value=form.value,result=await api('/bank-reconciliations/'+props.report.id+(props.post?'/entries':'/proposals'),{method:'POST',timeoutMs:90000,body:{version:props.report.version,request_id:requestId,movement_id:props.movement.id,date:value.date,concept:value.concept,remember:value.remember,rule_concept:value.rule_concept,counter_lines:value.counter_lines.map(line=>({account_id:Number(line.account_id),debit:line.debit.trim()||'0',credit:line.credit.trim()||'0'}))}});emit('saved',result);}catch(cause){error.value=reconciliationProposalError(cause);}finally{busy.value=false;}}
</script>
<template><FormDialog :title="post?'Assentament manual':'Preparar propuesta de asiento'" class="reconciliation-proposal-form" :busy="busy" @close="emit('close')"><p>{{ movement.concept }}</p><p class="muted">Banco {{ report.account.code }} · {{ report.account.description }} · {{ bankAmount<0n?'Pago':'Cobro' }} de {{ displayMoney(bankAmount<0n?-bankAmount:bankAmount) }} €. {{ post?'En guardar, l’assentament es registra al diari.':'La propuesta queda guardada en la conciliación para revisarla.' }}</p><p v-if="loading" role="status">Cargando subcuentas…</p><p v-if="error" class="notice error-notice" role="alert">{{ error }}</p><form @submit.prevent="save"><div class="proposal-fields"><label>Fecha del asiento<input v-model="form.date" name="proposal_date" type="date" :min="report.exercise.start_date" :max="report.exercise.end_date" required :disabled="busy"></label><label>Concepto del asiento<input v-model="form.concept" name="proposal_concept" maxlength="200" required :disabled="busy"></label></div><p class="proposal-bank-line"><strong>{{ report.account.code }} · {{ report.account.description }}</strong><span>Debe {{ bankAmount>0n?displayMoney(bankAmount):'0,00' }} € · Haber {{ bankAmount<0n?displayMoney(-bankAmount):'0,00' }} €</span></p><div class="table-wrap"><table class="proposal-counter-lines"><thead><tr><th>Contrapartida</th><th>Debe €</th><th>Haber €</th><th></th></tr></thead><tbody><tr v-for="(line,index) in form.counter_lines" :key="line.key"><td><SubaccountInput v-model="line.account_id" :accounts="accounts" :label="'Contrapartida '+(index+1)" :disabled="busy||loading" /><small>{{ name(line.account_id) }}</small></td><td><input v-model="line.debit" :aria-label="'Debe contrapartida '+(index+1)" inputmode="decimal" :disabled="busy"></td><td><input v-model="line.credit" :aria-label="'Haber contrapartida '+(index+1)" inputmode="decimal" :disabled="busy"></td><td><button v-if="form.counter_lines.length>1" type="button" class="button" :aria-label="'Quitar línea '+(index+1)" :disabled="busy" @click="form.counter_lines.splice(index,1)">×</button></td></tr></tbody></table></div><button type="button" class="button" :disabled="busy||form.counter_lines.length>=20" @click="addLine">Añadir contrapartida</button><div class="proposal-totals" aria-live="polite"><template v-if="totals.valid"><span>Debe <strong>{{ displayMoney(totals.debit) }} €</strong></span><span>Haber <strong>{{ displayMoney(totals.credit) }} €</strong></span><span>Diferencia <strong>{{ displayMoney(totals.difference) }} €</strong></span></template><span v-else>Revisa los importes.</span></div><label class="proposal-remember"><input v-model="form.remember" name="remember_criterion" type="checkbox" :disabled="busy">Recordar el criterio para próximos movimientos de este banco y sentido</label><label v-if="form.remember">Texto del concepto que se repite<input v-model="form.rule_concept" name="rule_concept" maxlength="200" minlength="3" required :disabled="busy"><small>Se propondrá para conceptos que contengan este texto en esta empresa y banco. Puedes acortarlo para quitar fechas o referencias que cambian.</small></label><p v-if="form.remember&&form.counter_lines.length>1" class="muted">En los siguientes movimientos se repartirá el importe proporcionalmente entre estas líneas. Podrás revisar y modificar la propuesta.</p><div class="actions"><button class="button primary" :disabled="!canSave">{{ busy?'Guardant…':post?'Guardar assentament':form.remember?'Guardar propuesta y criterio':'Guardar propuesta' }}</button><button type="button" class="button" :disabled="busy" @click="emit('close')">Cancelar</button></div></form></FormDialog></template>
<style scoped>.reconciliation-proposal-form>p{margin:15px 0;line-height:1.5}.proposal-fields{display:grid;grid-template-columns:180px 1fr;gap:16px}.proposal-bank-line{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;padding:14px;background:#f1f5f9;margin:18px 0}.proposal-counter-lines{width:100%;margin-bottom:16px}.proposal-counter-lines th:first-child{min-width:240px}.proposal-counter-lines input{max-width:100%}.proposal-counter-lines td:nth-child(2),.proposal-counter-lines td:nth-child(3){min-width:100px;width:130px}.proposal-counter-lines small{display:block;font-size:12px;margin-top:6px}.proposal-totals{display:flex;gap:25px;flex-wrap:wrap;margin:22px 0}.proposal-totals span{display:grid;gap:7px}.proposal-remember{display:flex;align-items:center;gap:10px;margin:20px 0}.proposal-remember input{width:auto}.reconciliation-proposal-form form>label>small{display:block;font-size:12px;line-height:1.5;color:#65748a;margin:8px 0}.reconciliation-proposal-form form>.actions{margin-top:22px}@media(max-width:650px){.proposal-fields{grid-template-columns:1fr}.proposal-counter-lines th:first-child{min-width:210px}}</style>
